/**
 * Demo: cubo posicionado sobre una imagen real, cuyo tamaño se escala segun
 * un mapa de profundidad generado por Depth Anything V2 (chenxwh/depth-anything-v2
 * en Replicate).
 *
 * Fuente de datos (ver README.md):
 *   data/background.jpg               -> imagen real (RGB)
 *   data/background/prediction-0.png  -> mapa de profundidad, escala de grises.
 *                                         Convencion del modelo: brillo alto (255) = cerca,
 *                                         brillo bajo (0) = lejos.
 *   data/background/prediction-1.png  -> version coloreada del propio modelo,
 *                                         usada solo para el toggle de visualizacion.
 */

// ---------- Config ajustable ----------
const IMG_SRC = 'data/background.jpg';
const DEPTH_VIS_SRC = 'data/background/prediction-1.png';
// prediction-0.png (mapa de profundidad crudo) va embebido mas abajo como DEPTH_DATA_URI, ver nota.

const MIN_SIZE = 16;        // px en pantalla (lado de la cara frontal), objeto mas lejano
const MAX_SIZE = 180;       // px en pantalla (lado de la cara frontal), objeto mas cercano
const SAMPLE_RADIUS = 6;    // radio (en px del mapa de profundidad) para promediar y evitar ruido
const CUBE_SKEW_X = 0.5;    // desplazamiento horizontal de las caras top/right, relativo al tamaño
const CUBE_SKEW_Y = 0.35;   // desplazamiento vertical de las caras top/right, relativo al tamaño
const VIEWPORT_FIT = 0.92;  // fraccion del alto de ventana que ocupa la imagen

// pares de caras opuestas: cada una comparte color con su opuesta (no visible)
const COLOR_TOP_BOTTOM = '#3b82f6';  // azul
const COLOR_FRONT_BACK = '#ef4444';  // rojo
const COLOR_LEFT_RIGHT = '#22c55e';  // verde

// ---------- Estado ----------
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const hud = document.getElementById('hud');
const toggleDepth = document.getElementById('toggleDepth');

const img = new Image();
const depthImg = new Image();
const depthVisImg = new Image();

let imgW = 0, imgH = 0;        // tamaño natural de la imagen real
let drawW = 0, drawH = 0;      // tamaño dibujado en canvas (ajustado al alto de la ventana)
let depthW = 0, depthH = 0;    // tamaño natural del mapa de profundidad
let depthData = null;          // Uint8ClampedArray RGBA del mapa de profundidad (offscreen)
let DEPTH_MIN = 0, DEPTH_MAX = 255;

let cube = null;   // {x, y, size, depth} -- (x,y) es el punto de la cara inferior (contacto con el suelo)
let dragging = false;
let ready = false;
let loaded = { img: false, depth: false, depthVis: false };

function onAnyLoaded(which) {
  loaded[which] = true;
  if (loaded.img && loaded.depth && loaded.depthVis) init();
}

img.onload = () => { imgW = img.naturalWidth; imgH = img.naturalHeight; onAnyLoaded('img'); };
depthImg.onload = () => { depthW = depthImg.naturalWidth; depthH = depthImg.naturalHeight; onAnyLoaded('depth'); };
depthVisImg.onload = () => onAnyLoaded('depthVis');

img.src = IMG_SRC;
// prediction-0.png se embebe en base64 (en vez de cargarse por ruta) porque es el unico
// asset del que se leen pixeles con getImageData; bajo file:// eso 'tainta' el canvas si
// la imagen se cargo como recurso cross-origin/opaco (background.jpg y prediction-1.png
// no tienen este problema porque solo se dibujan con drawImage, nunca se leen de vuelta).
const DEPTH_DATA_URI = "data:image/png;base64,";
depthImg.src = DEPTH_DATA_URI;
depthVisImg.src = DEPTH_VIS_SRC;

function init() {
  // Extrae los valores de profundidad (canal R, ya que es escala de grises) a resolucion nativa del PNG de profundidad.
  const off = document.createElement('canvas');
  off.width = depthW;
  off.height = depthH;
  const octx = off.getContext('2d');
  octx.drawImage(depthImg, 0, 0);
  depthData = octx.getImageData(0, 0, depthW, depthH).data;

  DEPTH_MIN = 255; DEPTH_MAX = 0;
  for (let i = 0; i < depthData.length; i += 4) {
    const v = depthData[i];
    if (v < DEPTH_MIN) DEPTH_MIN = v;
    if (v > DEPTH_MAX) DEPTH_MAX = v;
  }

  ready = true;
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  resize();
}

// La imagen se ajusta al alto de la ventana (sin scroll), manteniendo aspect ratio.
function resize() {
  if (!ready) return;
  const maxH = Math.floor(window.innerHeight * VIEWPORT_FIT) - 8; // 8px = padding del card
  const scale = maxH / imgH;
  drawW = Math.round(imgW * scale);
  drawH = Math.round(imgH * scale);
  canvas.width = drawW;
  canvas.height = drawH;
  render();
}
window.addEventListener('resize', resize);

// Lee profundidad promediando un area circular alrededor de (x,y) en coords de la imagen mostrada.
// Devuelve null si el punto cae fuera de los limites.
function sampleDepth(xImg, yImg) {
  if (xImg < 0 || yImg < 0 || xImg >= drawW || yImg >= drawH) return null;

  // El mapa de profundidad puede tener una resolucion ligeramente distinta a la imagen real;
  // se transforma la coordenada de forma proporcional.
  const dx = (xImg / drawW) * depthW;
  const dy = (yImg / drawH) * depthH;
  const cx = Math.round(dx);
  const cy = Math.round(dy);

  let sum = 0, count = 0;
  const r = SAMPLE_RADIUS;
  for (let oy = -r; oy <= r; oy++) {
    for (let ox = -r; ox <= r; ox++) {
      if (ox * ox + oy * oy > r * r) continue;
      const sx = cx + ox, sy = cy + oy;
      if (sx < 0 || sy < 0 || sx >= depthW || sy >= depthH) continue;
      const idx = (sy * depthW + sx) * 4;
      sum += depthData[idx]; // canal R (grayscale)
      count++;
    }
  }
  if (count === 0) return null;

  return { depth: sum / count };
}

function depthToSize(depth) {
  // brillo alto (cerca) -> cubo grande; brillo bajo (lejos) -> cubo chico
  let t = (depth - DEPTH_MIN) / (DEPTH_MAX - DEPTH_MIN);
  t = Math.min(1, Math.max(0, t));
  return MIN_SIZE + t * (MAX_SIZE - MIN_SIZE);
}

function placeOrMoveCube(x, y) {
  const s = sampleDepth(x, y);
  if (!s) return; // fuera de limites, ignorar
  const size = depthToSize(s.depth);
  cube = { x, y, size, depth: s.depth };
}

function render() {
  ctx.clearRect(0, 0, drawW, drawH);
  if (toggleDepth.checked) {
    ctx.drawImage(depthVisImg, 0, 0, drawW, drawH);
  } else {
    ctx.drawImage(img, 0, 0, drawW, drawH);
  }
  if (cube) drawCube(cube);
  updateHud();
}

// Calcula los vertices visibles del cubo. (x,y) = centro de la arista inferior de la cara
// frontal, es decir, el punto de apoyo en el suelo de la escena.
function cubeVertices(c) {
  const s = c.size;
  const skewX = s * CUBE_SKEW_X;
  const skewY = s * CUBE_SKEW_Y;

  const FBL = { x: c.x - s / 2, y: c.y };
  const FBR = { x: c.x + s / 2, y: c.y };
  const FTR = { x: c.x + s / 2, y: c.y - s };
  const FTL = { x: c.x - s / 2, y: c.y - s };

  const back = (p) => ({ x: p.x + skewX, y: p.y - skewY });
  const TTR = back(FTR);
  const TTL = back(FTL);
  const RBR = back(FBR);

  return { FBL, FBR, FTR, FTL, TTR, TTL, RBR, skewX, skewY };
}

function drawCube(c) {
  const v = cubeVertices(c);

  // cara superior (arriba/abajo)
  ctx.beginPath();
  ctx.moveTo(v.FTL.x, v.FTL.y);
  ctx.lineTo(v.FTR.x, v.FTR.y);
  ctx.lineTo(v.TTR.x, v.TTR.y);
  ctx.lineTo(v.TTL.x, v.TTL.y);
  ctx.closePath();
  ctx.fillStyle = COLOR_TOP_BOTTOM;
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.3)';
  ctx.stroke();

  // cara derecha (izquierda/derecha)
  ctx.beginPath();
  ctx.moveTo(v.FBR.x, v.FBR.y);
  ctx.lineTo(v.FTR.x, v.FTR.y);
  ctx.lineTo(v.TTR.x, v.TTR.y);
  ctx.lineTo(v.RBR.x, v.RBR.y);
  ctx.closePath();
  ctx.fillStyle = COLOR_LEFT_RIGHT;
  ctx.fill();
  ctx.stroke();

  // cara frontal (frente/atras)
  ctx.beginPath();
  ctx.moveTo(v.FBL.x, v.FBL.y);
  ctx.lineTo(v.FBR.x, v.FBR.y);
  ctx.lineTo(v.FTR.x, v.FTR.y);
  ctx.lineTo(v.FTL.x, v.FTL.y);
  ctx.closePath();
  ctx.fillStyle = COLOR_FRONT_BACK;
  ctx.fill();
  ctx.stroke();
}

function updateHud() {
  if (!cube) {
    hud.textContent = 'click / arrastra para colocar el cubo';
    return;
  }
  hud.textContent =
    `x: ${cube.x.toFixed(0)}  y: ${cube.y.toFixed(0)} (cara inferior)\n` +
    `depth (raw 0-255): ${cube.depth.toFixed(1)}\n` +
    `size: ${cube.size.toFixed(1)} px\n` +
    `depth range: ${DEPTH_MIN} .. ${DEPTH_MAX}`;
}

function getCanvasCoords(evt) {
  const rect = canvas.getBoundingClientRect();
  return { x: evt.clientX - rect.left, y: evt.clientY - rect.top };
}

// Test de "click cerca del cubo existente" usando el bounding box de sus vertices visibles.
function isNearCube(x, y) {
  if (!cube) return false;
  const v = cubeVertices(cube);
  const pts = [v.FBL, v.FBR, v.FTR, v.FTL, v.TTR, v.TTL, v.RBR];
  const minX = Math.min(...pts.map(p => p.x));
  const maxX = Math.max(...pts.map(p => p.x));
  const minY = Math.min(...pts.map(p => p.y));
  const maxY = Math.max(...pts.map(p => p.y));
  return x >= minX && x <= maxX && y >= minY && y <= maxY;
}

canvas.addEventListener('mousedown', (evt) => {
  const { x, y } = getCanvasCoords(evt);
  if (!isNearCube(x, y)) {
    placeOrMoveCube(x, y);
  }
  dragging = true;
  render();
});

window.addEventListener('mousemove', (evt) => {
  if (!dragging) return;
  const { x, y } = getCanvasCoords(evt);
  placeOrMoveCube(x, y);
  render();
});

window.addEventListener('mouseup', () => {
  dragging = false;
});

toggleDepth.addEventListener('change', render);

window.addEventListener('keydown', (evt) => {
  if (evt.key === 'd' || evt.key === 'D') {
    toggleDepth.checked = !toggleDepth.checked;
    render();
  }
});
